def words_under_1000(n, feminine=False):
    res = []
    h = n // 100
    if h:
        res.append(HUNDREDS[h])
    rem = n % 100
    if 10 <= rem <= 19:
        res.append(TEENS[rem - 10])
    else:
        t = rem // 10
        if t:
            res.append(TENS[t])
        u = rem % 10
        if u:
            if feminine and u in (1, 2):
                res.append({1: "одна", 2: "две"}[u])
            else:
                res.append(ONES[u])
    return res


def plural_ru(n, one, few, many):
    n10 = n % 10
    n100 = n % 100
    if n10 == 1 and n100 != 11:
        return one
    if 2 <= n10 <= 4 and not (12 <= n100 <= 14):
        return few
    return many


def num_to_ru(n):
    if n == 0:
        return "ноль"
    sign = ""
    if n < 0:
        sign = "минус "
        n = -n
    if n >= 10**12:
        return sign + str(n)

    groups = []
    groups.append((n % 1000, None))
    n //= 1000
    if n:
        groups.append((n % 1000, ("тысяча", "тысячи", "тысяч")))
    n //= 1000
    if n:
        groups.append((n % 1000, ("миллион", "миллиона", "миллионов")))
    n //= 1000
    if n:
        groups.append((n % 1000, ("миллиард", "миллиарда", "миллиардов")))
    n //= 1000
    if n:
        groups.append((n % 1000, ("триллион", "триллиона", "триллионов")))

    chunks = []
    for value, name_tuple in reversed(groups):
        if value == 0:
            continue
        feminine = name_tuple is not None and name_tuple[0] == "тысяча"
        words = words_under_1000(value, feminine=feminine)
        if name_tuple is not None:
            words.append(plural_ru(value, *name_tuple))
        chunks.append(" ".join(words))

    return (sign + " ".join(chunks)).strip()


