def ordinal_nominative(n):
    if n in ORD_NOM:
        return ORD_NOM[n]
    if n < 100:
        t = n // 10 * 10
        u = n % 10
        if u == 0:
            return TENS_GEN.get(n, num_to_ru(n))
        return (TENS_CARD.get(t, "") + " " + ORD_NOM[u]).strip()
    if n < 1000:
        h = n // 100
        rem = n % 100
        if rem == 0:
            return ORD_HUNDREDS[h]
        return (HUNDREDS[h] + " " + ordinal_nominative(rem)).strip()
    return num_to_ru(n)


