def ordinal_form(n, ending):
    s = ordinal_nominative(n)
    if n == 3:
        stem = "треть"
    elif s.endswith("ый") or s.endswith("ой"):
        stem = s[:-2]
    elif s.endswith("ий"):
        stem = s[:-2] + "ь"
    else:
        stem = s
    return stem + ending


def ordinal_dative(n):
    g = ordinal_genitive(n)
    if g.endswith("ого"):
        return g[:-3] + "ому"
    if g.endswith("его"):
        return g[:-3] + "ему"
    return g


def ordinal_instrumental(n):
    g = ordinal_genitive(n)
    if g.endswith("ого"):
        return g[:-3] + "ым"
    if g.endswith("его"):
        return g[:-3] + "им"
    return g


def ordinal_prepositional(n):
    g = ordinal_genitive(n)
    if g.endswith("ого"):
        return g[:-2] + "м"
    if g.endswith("его"):
        return g[:-2] + "м"
    return g


def year_phrase(year):
    if 2000 <= year <= 2099:
        rest = year % 100
        if rest == 0:
            return "двухтысячного года"
        return "две тысячи " + ordinal_genitive(rest) + " года"
    if 1000 <= year <= 1999:
        rest = year % 100
        if rest == 0:
            return "тысяча девятисотого года"
        return "тысяча девятьсот " + ordinal_genitive(rest) + " года"
    return num_to_ru(year) + " года"


def year_prepositional(year):
    if 2000 <= year <= 2099:
        rest = year % 100
        if rest == 0:
            return "двухтысячном"
        return "две тысячи " + ordinal_prepositional(rest)
    if 1000 <= year <= 1999:
        rest = year % 100
        if rest == 0:
            return "тысяча девятисотом"
        return "тысяча девятьсот " + ordinal_prepositional(rest)
    return num_to_ru(year)


def decimal_to_ru(s):
    sign = ""
    t = s
    if t.startswith("-"):
        sign = "минус "
        t = t[1:]
    if "," in t:
        int_s, frac_s = t.split(",")
    else:
        int_s, frac_s = t.split(".")
    n = int(int_s)
    denom = 10 ** len(frac_s)
    frac_n = int(frac_s)

    if n == 0:
        whole = "ноль целых"
    elif n == 1:
        whole = "одна целая"
    else:
        whole = num_to_ru_fem(n) + " целых"

    if denom == 10:
        frac_word = "одна десятая" if frac_n == 1 else (num_to_ru(frac_n) + " десятых")
    elif denom == 100:
        frac_word = "одна сотая" if frac_n == 1 else (num_to_ru(frac_n) + " сотых")
    elif denom == 1000:
        frac_word = (
            "одна тысячная" if frac_n == 1 else (num_to_ru(frac_n) + " тысячных")
        )
    else:
        frac_word = (
            num_to_ru(frac_n) + " " + plural_ru(frac_n, "часть", "части", "частей")
        )

    return sign + whole + " " + frac_word


def time_to_ru(s):
    m = TIME_RE.fullmatch(s)
    if not m:
        return s
    hh = int(m.group(1))
    mm = int(m.group(2))
    if mm == 0:
        return num_to_ru(hh) + " " + plural_ru(hh, "час", "часа", "часов")
    if hh == 0:
        return num_to_ru(mm) + " " + plural_ru(mm, "минута", "минуты", "минут")
    return num_to_ru(hh) + " " + num_to_ru(mm)


