def date_dotted_to_ru(s):
    parts = re.split(r"[./]", s)
    if len(parts) != 3:
        return s
    day = int(parts[0])
    month = int(parts[1])
    year = int(parts[2])
    if year < 100:
        year += 2000
    if not (1 <= month <= 12 and 1 <= day <= 31):
        return s
    return ordinal_genitive(day) + " " + MONTHS_GEN[month - 1] + " " + year_phrase(year)


def percent_to_ru(s):
    m = PERCENT_RE.fullmatch(s)
    if not m:
        return s
    num = m.group(1)
    if re.fullmatch(r"-?\d+", num):
        n = int(num)
        return (
            num_to_ru(n) + " " + plural_ru(abs(n), "процент", "процента", "процентов")
        )
    return decimal_to_ru(num) + " процента"


def fraction_slash_to_ru(num, denom):
    if num == 1:
        return "одна " + ordinal_form(denom, "ая")
    return num_to_ru_fem(num) + " " + ordinal_form(denom, "ых")


def roman_to_int(s):
    total = 0
    prev = 0
    for ch in reversed(s.upper()):
        val = ROMAN_MAP.get(ch, 0)
        if val == 0:
            return None
        if val < prev:
            total -= val
        else:
            total += val
            prev = val
    return total if total > 0 else None


def translit_latin(s):
    if not re.fullmatch(r"[A-Za-z]+", s):
        return ""
    if len(s) > 20:
        return ""
    parts = []
    for ch in s.upper():
        ru = LATIN_MAP.get(ch)
        if not ru:
            return ""
        for rch in ru:
            parts.append(rch + "_trans")
    return " ".join(parts)


def measure_to_ru(s):
    m = MEASURE_RE.fullmatch(s)
    if not m:
        return ""
    n_s, unit_s = m.group(1), m.group(2).lower()
    if not re.fullmatch(r"\d+", n_s):
        return ""
    n = int(n_s)
    unit = MEASURE_UNITS.get(unit_s)
    if unit is None:
        return ""
    return num_to_ru(n) + " " + plural_ru(n, *unit)


def money_to_ru(s):
    m = MONEY_SYM_RE.fullmatch(s)
    if m:
        n_s = m.group(2) if m.group(2) is not None else m.group(3)
        cur = m.group(1) if m.group(1) is not None else m.group(4)
        n = int(n_s)
        if cur == "$":
            unit = ("доллар", "доллара", "долларов")
        elif cur == "€":
            unit = ("евро", "евро", "евро")
        elif cur == "₽":
            unit = ("рубль", "рубля", "рублей")
        else:
            return ""
        return num_to_ru(n) + " " + plural_ru(n, *unit)

    m = MONEY_WORD_RE.fullmatch(s)
    if m:
        n = int(m.group(1))
        word = m.group(2).lower()
        if word.startswith("руб"):
            unit = ("рубль", "рубля", "рублей")
        elif word.startswith("долл"):
            unit = ("доллар", "доллара", "долларов")
        elif word == "евро":
            unit = ("евро", "евро", "евро")
        else:
            return ""
        return num_to_ru(n) + " " + plural_ru(n, *unit)

    return ""


@lru_cache(maxsize=500000)
def generate_candidates(before):
    s = before.strip()
    if not s or len(s) > 100:
        return ()

    out = []

    # Date with spaces: "12 февраля 2013"
    m = DATE_SPACE_YEAR_RE.fullmatch(s)
    if m:
        day = int(m.group(1))
        month = m.group(2).lower()
        year = int(m.group(3))
        if year < 100:
            year += 2000
        month_gen = MONTH_GEN.get(month)
        if month_gen is not None and 1 <= day <= 31:
            push_unique(
                out,
                [
                    f"{ordinal_genitive(day)} {month_gen} {year_phrase(year)}",
                    f"{ordinal_form(day, 'ое')} {month_gen} {year_phrase(year)}",
                    f"{ordinal_nominative(day)} {month_gen} {year_phrase(year)}",
                ],
            )
    else:
        # Date without year: "1 мая"
        m = NO_YEAR_DATE_RE.fullmatch(s)
        if m:
            day = int(m.group(1))
            month = m.group(2).lower()
            month_gen = MONTH_GEN.get(month)
            if month_gen is not None and 1 <= day <= 31:
                push_unique(
                    out,
                    [
                        f"{ordinal_genitive(day)} {month_gen}",
                        f"{ordinal_nominative(day)} {month_gen}",
                    ],
                )

    # Percent
    if PERCENT_RE.fullmatch(s):
        out.append(percent_to_ru(s))

    # Money / measure
    money = money_to_ru(s)
    if money:
        out.append(money)
    meas = measure_to_ru(s)
    if meas:
        out.append(meas)

    # Comma-separated thousands
    if COMMA_INT_RE.fullmatch(s):
        n = int(s.replace(",", ""))
        if abs(n) < 10**12:
            push_unique(
                out,
                [
                    num_to_ru(n),
                    num_to_ru_fem(n),
                    ordinal_nominative(n),
                    ordinal_genitive(n),
                ],
            )
            if 1000 <= n <= 2099:
                out.append(year_phrase(n))
                out.append(year_prepositional(n))

    # Decimal
    if DECIMAL_RE.fullmatch(s):
        out.append(decimal_to_ru(s))

    # Integer with possible space separators
    if INT_DIGITS_RE.fullmatch(s):
        d = s.replace(" ", "")
        try:
            n = int(d)
        except ValueError:
            n = None
        if n is not None and abs(n) < 10**12:
            push_unique(
                out,
                [
                    num_to_ru(n),
                    num_to_ru_fem(n),
                    ordinal_nominative(n),
                    ordinal_genitive(n),
                ],
            )
            if 1000 <= n <= 2099:
                out.append(year_phrase(n))
                out.append(year_prepositional(n))

    # Dotted / slashed date
    if re.fullmatch(r"\d{1,2}[./]\d{1,2}[./]\d{2,4}", s):
        out.append(date_dotted_to_ru(s))

    # Time
    if TIME_RE.fullmatch(s):
        out.append(time_to_ru(s))
        out.append(time_verbose_to_ru(s))

    # Slash fraction
    m = re.fullmatch(r"(\d+)\s*/\s*(\d+)", s)
    if m:
        num = int(m.group(1))
        denom = int(m.group(2))
        if denom > 0:
            out.append(fraction_slash_to_ru(num, denom))

    # Ordinal suffix: 1-й, 5-го, 3-му, ...
    m = re.fullmatch(r"(\d+)-?([а-яё]{2,4})", s)
    if m:
        n = int(m.group(1))
        suf = m.group(2)
        if suf in ("ый", "ой", "ий", "й"):
            out.append(ordinal_nominative(n))
        elif suf in ("ая", "яя"):
            out.append(ordinal_form(n, "ая"))
        elif suf in ("ое", "ее"):
            out.append(ordinal_form(n, "ое"))
        elif suf in ("ые", "ие"):
            out.append(ordinal_form(n, "ые"))
        elif suf in ("ого", "его", "го"):
            out.append(ordinal_genitive(n))
        elif suf in ("ому", "ему", "му"):
            out.append(ordinal_dative(n))
        elif suf in ("ым", "им"):
            out.append(ordinal_instrumental(n))
        elif suf in ("ом", "ем", "м"):
            out.append(ordinal_prepositional(n))
        elif suf in ("ых", "их", "х"):
            out.append(ordinal_form(n, "ых"))

    # Roman numeral
    if re.fullmatch(r"[IVXLCDM]+", s):
        n = roman_to_int(s)
        if n is not None:
            out.append(num_to_ru(n))
            out.append(ordinal_nominative(n))

    # Latin transliteration
    if re.fullmatch(r"[A-Za-z]+", s):
        t = translit_latin(s)
        if t:
            out.append(t)

    return tuple(out[:MAX_GEN])


def fallback_norm(s):
    if not isinstance(s, str):
        s = str(s)
    s = s.replace("\u00a0", " ").strip()
    if not s:
        return s

    m = DATE_RE.match(s)
    if m:
        day = int(m.group(1))
        month = m.group(2).lower()
        year = int(m.group(3))
        month_gen = MONTH_GEN.get(month)
        if month_gen and 1 <= day <= 31:
            return f"{ordinal_genitive(day)} {month_gen} {year_phrase(year)}"

    if re.fullmatch(r"\d{1,2}[./]\d{1,2}[./]\d{2,4}", s):
        return date_dotted_to_ru(s)

    if TIME_RE.fullmatch(s):
        return time_to_ru(s)

    if re.fullmatch(r"-?\d[\d ]*", s):
        t = s.replace(" ", "")
        try:
            n = int(t)
        except ValueError:
            return s
        if abs(n) < 10**12:
            return num_to_ru(n)

    if COMMA_INT_RE.fullmatch(s):
        t = s.replace(",", "")
        try:
            n = int(t)
        except ValueError:
            return s
        if abs(n) < 10**12:
            return num_to_ru(n)

    if DECIMAL_RE.fullmatch(s):
        return decimal_to_ru(s)

    if PERCENT_RE.fullmatch(s):
        return percent_to_ru(s)

    m = re.fullmatch(r"(\d+)\s*/\s*(\d+)", s)
    if m:
        num = int(m.group(1))
        denom = int(m.group(2))
        if denom > 0:
            return fraction_slash_to_ru(num, denom)

    m = re.fullmatch(r"(\d+)-?([а-яё]{2,4})", s)
    if m:
        n = int(m.group(1))
        suf = m.group(2)
        if suf in ("ый", "ой", "ий", "й"):
            return ordinal_nominative(n)
        if suf in ("ая", "яя"):
            return ordinal_form(n, "ая")
        if suf in ("ое", "ее"):
            return ordinal_form(n, "ое")
        if suf in ("ые", "ие"):
            return ordinal_form(n, "ые")
        if suf in ("ого", "его", "го"):
            return ordinal_genitive(n)
        if suf in ("ому", "ему", "му"):
            return ordinal_dative(n)
        if suf in ("ым", "им"):
            return ordinal_instrumental(n)
        if suf in ("ом", "ем", "м"):
            return ordinal_prepositional(n)
        if suf in ("ых", "их", "х"):
            return ordinal_form(n, "ых")

    if re.fullmatch(r"[IVXLCDM]+", s):
        n = roman_to_int(s)
        if n is not None:
            return ordinal_nominative(n)

    if re.fullmatch(r"[A-Za-z]+", s):
        t = translit_latin(s)
        if t:
            return t

    money = money_to_ru(s)
    if money:
        return money
    meas = measure_to_ru(s)
    if meas:
        return meas

    return s


def fallback_norm_ctx(s, prev_s, next_s):
    orig = str(s).strip()
    p = str(prev_s).strip().lower()
    nx = str(next_s).strip().lower()

    # A day-like number followed by a month -> genitive date ordinal.
    if re.fullmatch(r"\d{1,2}", orig):
        d = int(orig)
        if 1 <= d <= 31 and nx in MONTH_NAMES:
            return f"{ordinal_genitive(d)} {MONTH_GEN[nx]}"

    # A year-like number after a month -> year phrase.
    if re.fullmatch(r"-?\d{3,4}", orig):
        n = int(orig)
        if 1000 <= n <= 2099:
            if p in MONTH_NAMES:
                return year_phrase(n)
            if nx == "году":
                return year_prepositional(n)

    return fallback_norm(orig)


