def series_to_obj_index(s):
    df = s.reset_index()
    key_cols = list(df.columns[:-1])
    df.columns = key_cols + ["count"]
    for col in key_cols:
        df[col] = df[col].astype(str)
    return df.set_index(key_cols)["count"].astype("int32")


def subtract_counts(full, val):
    res = full.sub(val, fill_value=0)
    res = res[res > 0]
    return res.astype("int32")


def add_context(df):
    sent = df["sentence_id"].to_numpy()
    b = df["before"]

    if "" not in b.cat.categories:
        b = b.cat.add_categories("")
        df["before"] = b

    prev = b.shift(1).fillna("").copy()
    is_first = np.zeros(len(df), dtype=bool)
    is_first[0] = True
    is_first[1:] = sent[1:] != sent[:-1]
    prev[is_first] = ""

    nxt = b.shift(-1).fillna("").copy()
    is_last = np.zeros(len(df), dtype=bool)
    is_last[-1] = True
    is_last[:-1] = sent[:-1] != sent[1:]
    nxt[is_last] = ""

    df["prev_before"] = prev
    df["next_before"] = nxt
    df["sentence_len_tokens"] = (
        df.groupby("sentence_id")["token_id"].transform("size").astype(np.int16)
    )


def string_features(s):
    s = s.astype(str)
    out = pd.DataFrame(
        {
            "len": s.str.len(),
            "digits": s.str.count(r"\d"),
            "letters": s.str.count(r"[A-Za-zА-Яа-яЁё]"),
            "spaces": s.str.count(r"\s"),
            "dash": s.str.count("-"),
            "punct": s.str.count(r"[^\w\s]"),
        },
        index=s.index,
    )
    return out.astype(np.float32)


def pattern_features(rows):
    b = rows["before"].astype(str)
    pf = pd.DataFrame(index=rows.index)
    pf["before_is_int"] = b.str.fullmatch(r"-?\d[\d ]*", na=False).astype(np.int8)
    pf["before_has_comma_int"] = b.str.fullmatch(
        r"-?\d{1,3}(?:,\d{3})+", na=False
    ).astype(np.int8)
    pf["before_has_decimal"] = b.str.fullmatch(r"-?\d+[.,]\d+", na=False).astype(
        np.int8
    )
    pf["before_has_percent"] = b.str.contains(r"%", regex=False, na=False).astype(
        np.int8
    )
    pf["before_has_date_spaces"] = b.str.fullmatch(
        r"\d{1,2}\s+[А-Яа-яЁё]+\s+\d{2,4}", na=False
    ).astype(np.int8)
    pf["before_has_dotted_date"] = b.str.fullmatch(
        r"\d{1,2}[./]\d{1,2}[./]\d{2,4}", na=False
    ).astype(np.int8)
    pf["before_has_time"] = b.str.fullmatch(r"\d{1,2}:\d{2}", na=False).astype(np.int8)
    pf["before_has_ord_suffix"] = b.str.fullmatch(r"\d+-?[а-яё]{2,4}", na=False).astype(
        np.int8
    )
    pf["before_has_roman"] = b.str.fullmatch(r"[IVXLCDM]+", na=False).astype(np.int8)
    pf["before_has_latin"] = b.str.fullmatch(r"[A-Za-z]+", na=False).astype(np.int8)
    pf["before_has_measure"] = b.str.contains(
        r"^-?\d+\s*(км|м|см|мм|кг|г|л|мл|га|т|кВт|В|А)\b",
        regex=True,
        na=False,
    ).astype(np.int8)
    pf["before_has_money"] = b.str.contains(
        r"[$€₽]|\d+\s*(руб|долл|евро)", regex=True, na=False
    ).astype(np.int8)
    return pf


def build_candidate_table(base_ba_counts, amb_before_full, full_amb_pairs=None):
    if len(amb_before_full) == 0:
        return pd.DataFrame(columns=["before", "after", "count", "source"]), pd.Index(
            []
        )

    if base_ba_counts is None or len(base_ba_counts) == 0:
        base_df = pd.DataFrame(columns=["before", "after", "count"])
    else:
        base_df = base_ba_counts.reset_index()
        base_df.columns = ["before", "after", "count"]
        base_df = base_df[base_df["before"].isin(amb_before_full)]

    multi_before = pd.Index(amb_before_full)
    if len(base_df):
        base_df = base_df.copy()
        base_df["source"] = 0
        cand_df = base_df[["before", "after", "count", "source"]].copy()
    else:
        cand_df = pd.DataFrame(columns=["before", "after", "count", "source"])

    present_before = set(cand_df["before"])
    present_self = set(cand_df.loc[cand_df["before"] == cand_df["after"], "before"])
    missing_self = multi_before.difference(present_self)
    if len(missing_self):
        self_df = pd.DataFrame(
            {
                "before": list(missing_self),
                "after": list(missing_self),
                "count": 0,
                "source": 2,
            }
        )
        cand_df = pd.concat([cand_df, self_df], ignore_index=True)

    gen_rows = []
    for b in multi_before:
        for cand in generate_candidates(str(b)):
            gen_rows.append((str(b), cand, 0, 1))

    if gen_rows:
        gen_df = pd.DataFrame(gen_rows, columns=["before", "after", "count", "source"])
        cand_df = pd.concat([cand_df, gen_df], ignore_index=True)

    # Add full-training observed alternatives even if absent from this fold.
    if full_amb_pairs is not None and len(full_amb_pairs) > 0:
        full_df = full_amb_pairs[full_amb_pairs["before"].isin(amb_before_full)].copy()
        if len(full_df):
            cand_df["__key"] = (
                cand_df["before"].astype(str) + "\x00" + cand_df["after"].astype(str)
            )
            full_df["__key"] = (
                full_df["before"].astype(str) + "\x00" + full_df["after"].astype(str)
            )
            missing = full_df.loc[
                ~full_df["__key"].isin(cand_df["__key"]), ["before", "after"]
            ].copy()
            missing["count"] = 0
            missing["source"] = 3
            cand_df = cand_df.drop(columns="__key")
            cand_df = pd.concat([cand_df, missing], ignore_index=True)

    cand_df = cand_df.drop_duplicates(["before", "after"], keep="first").reset_index(
        drop=True
    )
    return cand_df, multi_before


def build_class_pivot(base_class_counts, multi_before, classes):
    empty = pd.DataFrame(
        {"before": pd.Series(dtype=str), "after": pd.Series(dtype=str)}
    )
    for c in classes:
        empty[c] = 0.0

    if (
        base_class_counts is None
        or len(base_class_counts) == 0
        or len(multi_before) == 0
    ):
        return empty

    df = base_class_counts.reset_index()
    df.columns = ["before", "after", "class", "count"]
    df = df[df["before"].isin(multi_before)]
    if len(df) == 0:
        return empty

    df["class"] = df["class"].astype(str)
    pivot = df.pivot_table(
        index=["before", "after"], columns="class", values="count", fill_value=0
    ).reset_index()
    pivot.columns = [str(c) for c in pivot.columns]

    for c in classes:
        if c not in pivot.columns:
            pivot[c] = 0.0
    return pivot


def make_train_rows(base_df, cand_df, multi_before):
    if len(multi_before) == 0 or len(cand_df) == 0:
        return pd.DataFrame()

    amb = base_df.loc[
        base_df["before"].isin(multi_before),
        [
            "before",
            "prev_before",
            "next_before",
            "after",
            "token_id",
            "sentence_len_tokens",
        ],
    ].copy()
    if len(amb) == 0:
        return pd.DataFrame()

    amb = amb.reset_index(drop=True)
    amb[["before", "prev_before", "next_before", "after"]] = amb[
        ["before", "prev_before", "next_before", "after"]
    ].astype(str)

    rows = amb.rename(columns={"after": "true_after"}).merge(
        cand_df, on="before", how="left"
    )
    if len(rows) == 0:
        return rows

    rows["label"] = (rows["true_after"] == rows["after"]).astype(np.int8)
    return rows


def add_features(
    rows,
    left_counts,
    right_counts,
    class_pivot,
    classes,
    left_backoff_counts,
    right_backoff_counts,
    left_right_backoff_counts,
    after_counts,
):
    rows = rows.reset_index(drop=True)

    bf = string_features(rows["before"])
    bf.columns = ["before_" + c for c in bf.columns]
    af = string_features(rows["after"])
    af.columns = ["after_" + c for c in af.columns]
    pf = string_features(rows["prev_before"])
    pf.columns = ["prev_" + c for c in pf.columns]
    nf = string_features(rows["next_before"])
    nf.columns = ["next_" + c for c in nf.columns]

    pat = pattern_features(rows)

    rows = pd.concat([rows, bf, af, pf, nf, pat], axis=1)

    prev_s = rows["prev_before"].astype(str)
    next_s = rows["next_before"].astype(str)
    rows["prev_is_month"] = prev_s.isin(MONTH_NAMES).astype(np.int8)
    rows["next_is_month"] = next_s.isin(MONTH_NAMES).astype(np.int8)
    rows["prev_is_year_word"] = prev_s.isin(YEAR_WORDS).astype(np.int8)
    rows["next_is_year_word"] = next_s.isin(YEAR_WORDS).astype(np.int8)
    rows["prev_is_prep"] = prev_s.isin(PREP_SET).astype(np.int8)
    rows["next_is_prep"] = next_s.isin(PREP_SET).astype(np.int8)
    rows["prev_is_int"] = prev_s.str.fullmatch(r"\d+", na=False).astype(np.int8)
    rows["next_is_int"] = next_s.str.fullmatch(r"\d+", na=False).astype(np.int8)
    rows["prev_is_year"] = prev_s.str.fullmatch(r"(?:19|20)\d{2}", na=False).astype(
        np.int8
    )
    rows["next_is_year"] = next_s.str.fullmatch(r"(?:19|20)\d{2}", na=False).astype(
        np.int8
    )

    if "token_id" in rows.columns and "sentence_len_tokens" in rows.columns:
        rows["token_frac"] = (
            rows["token_id"].astype(np.float32)
            / rows["sentence_len_tokens"].astype(np.float32).clip(lower=1)
        ).astype(np.float32)
        rows["is_first_token"] = (rows["token_id"].astype(np.int32) == 0).astype(
            np.int8
        )
        rows["is_last_token"] = (
            rows["token_id"].astype(np.int32)
            == rows["sentence_len_tokens"].astype(np.int32) - 1
        ).astype(np.int8)
    else:
        rows["token_frac"] = 0.0
        rows["is_first_token"] = 0
        rows["is_last_token"] = 0

    left_idx = pd.MultiIndex.from_arrays(
        [rows["before"], rows["prev_before"], rows["after"]]
    )
    rows["left_count"] = (
        left_counts.reindex(left_idx).fillna(0).to_numpy().astype(np.float32)
    )

    right_idx = pd.MultiIndex.from_arrays(
        [rows["before"], rows["next_before"], rows["after"]]
    )
    rows["right_count"] = (
        right_counts.reindex(right_idx).fillna(0).to_numpy().astype(np.float32)
    )

    lb_idx = pd.MultiIndex.from_arrays([rows["prev_before"], rows["after"]])
    rows["left_backoff"] = (
        left_backoff_counts.reindex(lb_idx).fillna(0).to_numpy().astype(np.float32)
    )

    rb_idx = pd.MultiIndex.from_arrays([rows["next_before"], rows["after"]])
    rows["right_backoff"] = (
        right_backoff_counts.reindex(rb_idx).fillna(0).to_numpy().astype(np.float32)
    )

    lrb_idx = pd.MultiIndex.from_arrays(
        [rows["prev_before"], rows["next_before"], rows["after"]]
    )
    rows["left_right_backoff"] = (
        left_right_backoff_counts.reindex(lrb_idx)
        .fillna(0)
        .to_numpy()
        .astype(np.float32)
    )

    rows["global_after_count"] = (
        after_counts.reindex(rows["after"]).fillna(0).to_numpy().astype(np.float32)
    )

    rows["cand_count"] = rows["count"].astype(np.float32)
    rows["cand_rank"] = (
        rows.groupby("before")["count"]
        .rank(ascending=False, method="min")
        .astype(np.float32)
    )

    total_count = rows.groupby("before")["count"].transform("sum").replace(0, 1)
    rows["before_total"] = total_count.astype(np.float32)
    rows["cand_share"] = (rows["count"] / total_count).astype(np.float32)
    rows["equal_self"] = (rows["before"] == rows["after"]).astype(np.int8)

    if "source" in rows.columns:
        rows["cand_source"] = rows["source"].fillna(0).astype(np.float32)
    else:
        rows["cand_source"] = 0.0
    rows["is_generated"] = (rows["cand_source"] == 1).astype(np.int8)
    rows["is_full_observed"] = (rows["cand_source"] == 3).astype(np.int8)

    rows["after_word_count"] = (
        rows["after"].astype(str).str.split().str.len().fillna(0).astype(np.float32)
    )
    rows["after_has_trans"] = (
        rows["after"]
        .astype(str)
        .str.contains("_trans", regex=False, na=False)
        .astype(np.int8)
    )

    rows = rows.merge(class_pivot, on=["before", "after"], how="left")
    for c in classes:
        if c not in rows.columns:
            rows[c] = 0.0
        rows[c] = rows[c].fillna(0).astype(np.float32)

    rows["class_max"] = rows[classes].max(axis=1).astype(np.float32)
    return rows


def train_lgb(rows, feature_cols, seed):
    X = rows[feature_cols].fillna(0).astype(np.float32)
    y = rows["label"].astype(np.int32)

    params = {
        "objective": "binary",
        "metric": "binary_logloss",
        "learning_rate": 0.05,
        "num_leaves": 95,
        "min_data_in_leaf": 50,
        "feature_fraction": 0.8,
        "bagging_fraction": 0.8,
        "bagging_freq": 1,
        "lambda_l2": 1.0,
        "verbosity": -1,
        "num_threads": 8,
        "seed": seed,
    }

    dset = lgb.Dataset(X, y)
    model = lgb.train(params, dset, num_boost_round=LGB_ROUNDS)
    return model


def score_candidates(
    pred_subset,
    cand_df,
    left_counts,
    right_counts,
    class_pivot,
    model,
    feature_cols,
    classes,
    left_backoff_counts,
    right_backoff_counts,
    left_right_backoff_counts,
    after_counts,
):
    rows = pred_subset.merge(cand_df, on="before", how="left")
    if len(rows) == 0:
        return pd.Series(dtype=str)

    rows = add_features(
        rows,
        left_counts,
        right_counts,
        class_pivot,
        classes,
        left_backoff_counts,
        right_backoff_counts,
        left_right_backoff_counts,
        after_counts,
    )

    if model is not None:
        rows["score"] = model.predict(rows[feature_cols].fillna(0).astype(np.float32))
    else:
        rows["score"] = (
            rows["cand_count"]
            + rows["left_count"]
            + rows["right_count"]
            + rows["left_backoff"]
            + rows["right_backoff"]
            + rows["left_right_backoff"]
        )

    best_idx = rows.groupby("orig_idx")["score"].idxmax()
    best = rows.loc[best_idx].set_index("orig_idx")["after"]
    return best


def predict_df(
    df,
    ba_counts,
    left_counts,
    right_counts,
    class_pivot,
    model,
    multi_before,
    cand_df,
    feature_cols,
    classes,
    left_backoff_counts,
    right_backoff_counts,
    left_right_backoff_counts,
    after_counts,
):
    pred = df["before"].astype(str).copy()
    known = pd.Series(False, index=df.index, dtype=bool)

    ba_df = ba_counts.reset_index()
    ba_df.columns = ["before", "after", "count"]
    sizes = ba_df.groupby("before")["after"].nunique()
    unamb_before = sizes[sizes == 1].index.difference(multi_before)

    if len(unamb_before) > 0:
        unamb_map = ba_df[ba_df["before"].isin(unamb_before)].set_index("before")[
            "after"
        ]
        idx = df["before"].isin(unamb_map.index)
        if idx.any():
            pred.loc[idx] = df.loc[idx, "before"].map(unamb_map).astype(str)
            known.loc[idx] = True

    if len(multi_before) > 0 and len(cand_df) > 0:
        idx = df["before"].isin(multi_before)
        if idx.any():
            sub = pd.DataFrame(
                {
                    "orig_idx": np.arange(idx.sum()),
                    "before": df.loc[idx, "before"].astype(str).to_numpy(),
                    "prev_before": df.loc[idx, "prev_before"].astype(str).to_numpy(),
                    "next_before": df.loc[idx, "next_before"].astype(str).to_numpy(),
                    "token_id": df.loc[idx, "token_id"].astype(np.int32).to_numpy(),
                    "sentence_len_tokens": df.loc[idx, "sentence_len_tokens"]
                    .astype(np.int32)
                    .to_numpy(),
                }
            )
            best = score_candidates(
                sub,
                cand_df,
                left_counts,
                right_counts,
                class_pivot,
                model,
                feature_cols,
                classes,
                left_backoff_counts,
                right_backoff_counts,
                left_right_backoff_counts,
                after_counts,
            )
            pred.loc[idx] = best.reindex(np.arange(idx.sum())).to_numpy()
            known.loc[idx] = True

    unknown = ~known
    if unknown.any():
        unk_df = df.loc[unknown, ["before", "prev_before", "next_before"]].astype(str)
        uniq = unk_df.drop_duplicates().reset_index(drop=True)
        fmap = {}
        for row in uniq.itertuples(index=False):
            fmap[(row.before, row.prev_before, row.next_before)] = fallback_norm_ctx(
                row.before, row.prev_before, row.next_before
            )
        pred.loc[unknown] = unk_df.apply(
            lambda r: fmap[(r["before"], r["prev_before"], r["next_before"])], axis=1
        ).astype(str)

    return pred


# ----------------------------------------------------------------------------
# Main
# ----------------------------------------------------------------------------


def main():
    t0 = time.time()

    train = pd.read_csv(
        "data/ru_train.csv",
        usecols=["sentence_id", "token_id", "before", "after", "class"],
        dtype={
            "sentence_id": "int32",
            "token_id": "int16",
            "before": "category",
            "after": "category",
            "class": "category",
        },
    )
    test = pd.read_csv(
        "data/ru_test_2.csv",
        usecols=["sentence_id", "token_id", "before"],
        dtype={
            "sentence_id": "int32",
            "token_id": "int16",
            "before": "category",
        },
    )

    train = train.sort_values(
        ["sentence_id", "token_id"], kind="mergesort"
    ).reset_index(drop=True)
    test = test.sort_values(["sentence_id", "token_id"], kind="mergesort").reset_index(
        drop=True
    )

    add_context(train)
    add_context(test)

    classes = sorted(train["class"].cat.categories.tolist())
    print("Prepared data", time.time() - t0, flush=True)

    ba_counts = series_to_obj_index(
        train.groupby(["before", "after"], observed=True).size()
    )

    ba_df = ba_counts.reset_index()
    ba_df.columns = ["before", "after", "count"]
    amb_counts = ba_df.groupby("before")["after"].nunique()
    amb_before_full = amb_counts[amb_counts > 1].index
    full_amb_pairs = ba_df[ba_df["before"].isin(amb_before_full)].copy()
    del ba_df
    gc.collect()

    amb_mask_full = train["before"].isin(amb_before_full)
    train_amb = train.loc[
        amb_mask_full, ["before", "prev_before", "next_before", "after"]
    ]

    left_counts = series_to_obj_index(
        train_amb.groupby(["before", "prev_before", "after"], observed=True).size()
    )
    right_counts = series_to_obj_index(
        train_amb.groupby(["before", "next_before", "after"], observed=True).size()
    )
    class_counts = series_to_obj_index(
        train.loc[amb_mask_full, ["before", "after", "class"]]
        .groupby(["before", "after", "class"], observed=True)
        .size()
    )

    left_backoff_counts = series_to_obj_index(
        train_amb.groupby(["prev_before", "after"], observed=True).size()
    )
    right_backoff_counts = series_to_obj_index(
        train_amb.groupby(["next_before", "after"], observed=True).size()
    )
    left_right_backoff_counts = series_to_obj_index(
        train_amb.groupby(["prev_before", "next_before", "after"], observed=True).size()
    )
    after_counts = series_to_obj_index(train.groupby("after", observed=True).size())

    del train_amb, amb_mask_full
    gc.collect()

    base_feat = [
        "cand_count",
        "cand_rank",
        "cand_share",
        "before_total",
        "left_count",
        "right_count",
        "left_backoff",
        "right_backoff",
        "left_right_backoff",
        "global_after_count",
        "equal_self",
        "cand_source",
        "is_generated",
        "is_full_observed",
        "after_word_count",
        "after_has_trans",
        "before_is_int",
        "before_has_comma_int",
        "before_has_decimal",
        "before_has_percent",
        "before_has_date_spaces",
        "before_has_dotted_date",
        "before_has_time",
        "before_has_ord_suffix",
        "before_has_roman",
        "before_has_latin",
        "before_has_measure",
        "before_has_money",
        "prev_is_month",
        "next_is_month",
        "prev_is_year_word",
        "next_is_year_word",
        "prev_is_prep",
        "next_is_prep",
        "prev_is_int",
        "next_is_int",
        "prev_is_year",
        "next_is_year",
        "token_frac",
        "is_first_token",
        "is_last_token",
    ]
    string_feat = [
        f"{p}_{s}"
        for p in ["before", "after", "prev", "next"]
        for s in ["len", "digits", "letters", "spaces", "dash", "punct"]
    ]
    feature_cols = base_feat + string_feat + ["class_max"] + classes

    unique_sids = np.unique(train["sentence_id"].to_numpy())
    kf = KFold(n_splits=5, shuffle=True, random_state=42)
    total_correct = 0
    total = 0

    for fold, (_, val_idx) in enumerate(kf.split(unique_sids)):
        val_sids = pd.Index(unique_sids[val_idx])
        val_mask = train["sentence_id"].isin(val_sids)
        val_df = train.loc[val_mask]
        base_df = train.loc[~val_mask]

        val_ba_counts = series_to_obj_index(
            val_df.groupby(["before", "after"], observed=True).size()
        )
        base_ba_counts = subtract_counts(ba_counts, val_ba_counts)

        val_amb = val_df[val_df["before"].isin(amb_before_full)]

        val_left_counts = series_to_obj_index(
            val_amb.groupby(["before", "prev_before", "after"], observed=True).size()
        )
        base_left_counts = subtract_counts(left_counts, val_left_counts)

        val_right_counts = series_to_obj_index(
            val_amb.groupby(["before", "next_before", "after"], observed=True).size()
        )
        base_right_counts = subtract_counts(right_counts, val_right_counts)

        val_class_counts = series_to_obj_index(
            val_amb.groupby(["before", "after", "class"], observed=True).size()
        )
        base_class_counts = subtract_counts(class_counts, val_class_counts)

        val_left_backoff = series_to_obj_index(
            val_amb.groupby(["prev_before", "after"], observed=True).size()
        )
        base_left_backoff = subtract_counts(left_backoff_counts, val_left_backoff)

        val_right_backoff = series_to_obj_index(
            val_amb.groupby(["next_before", "after"], observed=True).size()
        )
        base_right_backoff = subtract_counts(right_backoff_counts, val_right_backoff)

        val_left_right_backoff = series_to_obj_index(
            val_amb.groupby(
                ["prev_before", "next_before", "after"], observed=True
            ).size()
        )
        base_left_right_backoff = subtract_counts(
            left_right_backoff_counts, val_left_right_backoff
        )

        val_after_counts = series_to_obj_index(
            val_df.groupby("after", observed=True).size()
        )
        base_after_counts = subtract_counts(after_counts, val_after_counts)

        cand_df, multi_before = build_candidate_table(
            base_ba_counts, amb_before_full, full_amb_pairs
        )
        class_pivot = build_class_pivot(base_class_counts, multi_before, classes)

        train_rows = make_train_rows(base_df, cand_df, multi_before)
        if len(train_rows) > TRAIN_CAP:
            train_rows = train_rows.sample(TRAIN_CAP, random_state=42 + fold)
            train_rows = train_rows.reset_index(drop=True)

        if len(train_rows) > 0:
            train_rows = add_features(
                train_rows,
                base_left_counts,
                base_right_counts,
                class_pivot,
                classes,
                base_left_backoff,
                base_right_backoff,
                base_left_right_backoff,
                base_after_counts,
            )
            model = train_lgb(train_rows, feature_cols, 42 + fold)
        else:
            model = None

        preds = predict_df(
            val_df,
            base_ba_counts,
            base_left_counts,
            base_right_counts,
            class_pivot,
            model,
            multi_before,
            cand_df,
            feature_cols,
            classes,
            base_left_backoff,
            base_right_backoff,
            base_left_right_backoff,
            base_after_counts,
        )
        correct = int(
            (preds.to_numpy() == val_df["after"].astype(str).to_numpy()).sum()
        )
        total_correct += correct
        total += len(val_df)

        print(
            f"Fold {fold + 1}: accuracy {correct / len(val_df):.5f} "
            f"({time.time() - t0:.1f}s)",
            flush=True,
        )

        del val_ba_counts, base_ba_counts, val_left_counts, base_left_counts
        del val_right_counts, base_right_counts, val_class_counts, base_class_counts
        del val_left_backoff, base_left_backoff, val_right_backoff, base_right_backoff
        del val_left_right_backoff, base_left_right_backoff
        del val_after_counts, base_after_counts
        del cand_df, class_pivot, train_rows, model, preds
        gc.collect()

    cv_acc = total_correct / total
    print(f"CV accuracy: {cv_acc:.5f}", flush=True)

    print("Training final model on full training data", time.time() - t0, flush=True)
    cand_df, multi_before = build_candidate_table(
        ba_counts, amb_before_full, full_amb_pairs
    )
    class_pivot = build_class_pivot(class_counts, multi_before, classes)

    final_rows = make_train_rows(train, cand_df, multi_before)
    if len(final_rows) > TRAIN_CAP:
        final_rows = final_rows.sample(TRAIN_CAP, random_state=42)
        final_rows = final_rows.reset_index(drop=True)

    final_rows = add_features(
        final_rows,
        left_counts,
        right_counts,
        class_pivot,
        classes,
        left_backoff_counts,
        right_backoff_counts,
        left_right_backoff_counts,
        after_counts,
    )
    final_model = train_lgb(final_rows, feature_cols, 42)

    print("Predicting test", time.time() - t0, flush=True)
    test_preds = predict_df(
        test,
        ba_counts,
        left_counts,
        right_counts,
        class_pivot,
        final_model,
        multi_before,
        cand_df,
        feature_cols,
        classes,
        left_backoff_counts,
        right_backoff_counts,
        left_right_backoff_counts,
        after_counts,
    )

    sub = pd.DataFrame(
        {
            "id": test["sentence_id"].astype(str) + "_" + test["token_id"].astype(str),
            "after": test_preds.astype(str),
        }
    )
    sub.to_csv("submission.csv", index=False)
    print(
        f"Saved submission.csv with {len(sub)} rows ({time.time() - t0:.1f}s)",
        flush=True,
    )


if __name__ == "__main__":
    main()
